'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { addNews, saveDraft } from '@/lib/supabase'
import ImageUpload from '@/components/ImageUpload'

export default function NewNewsPage() {
  const [formData, setFormData] = useState({
    title: '',
    excerpt: '',
    content: '',
    category: '',
    author: '',
    featured: false,
    imageUrl: '',
    images: [] as string[],
    videoUrl: '',
    isPublished: false, // Admin onayı için
    isDraft: true, // Taslak olarak başlar
  })

  const [autoSaveEnabled, setAutoSaveEnabled] = useState(true)
  const [lastSaved, setLastSaved] = useState<string | null>(null)

  const categories = ['Gündem', 'Siyaset', 'Ekonomi', 'Spor', 'Magazin', 'Teknoloji']

  // LocalStorage'dan form verilerini yükle
  useEffect(() => {
    const savedData = localStorage.getItem('newsDraft')
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData)
        setFormData(prev => ({ ...prev, ...parsed }))
      } catch (error) {
        console.error('Error loading draft:', error)
      }
    }
  }, [])

  // Form verilerini localStorage'a kaydet (auto-save)
  useEffect(() => {
    if (autoSaveEnabled && formData.title) {
      const timer = setTimeout(() => {
        localStorage.setItem('newsDraft', JSON.stringify(formData))
        setLastSaved(new Date().toLocaleTimeString('tr-TR'))
      }, 2000) // 2 saniye sonra kaydet

      return () => clearTimeout(timer)
    }
  }, [formData, autoSaveEnabled])

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value
    }))
  }

  const handleImageSelect = (url: string) => {
    if (!formData.imageUrl) {
      // Ana resim yoksa, seçileni ana resim yap
      setFormData(prev => ({ ...prev, imageUrl: url }))
    } else {
      // Ana resim varsa, ek resimler listesine ekle
      setFormData(prev => ({
        ...prev,
        images: [...prev.images, url]
      }))
    }
  }

  const handleRemoveImage = (index: number) => {
    setFormData(prev => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index)
    }))
  }

  const saveAsDraft = async () => {
    try {
      const draftData = {
        ...formData,
        image_url: formData.imageUrl,
        is_published: formData.isPublished,
        is_draft: formData.isDraft
      }
      const success = await saveDraft(draftData)

      if (success) {
        localStorage.removeItem('newsDraft') // Taslak kaydedildi, localStorage'ı temizle
        setLastSaved(new Date().toLocaleTimeString('tr-TR'))
        alert('Taslak başarıyla kaydedildi!')
      } else {
        alert('Taslak kaydedilirken hata oluştu!')
      }
    } catch (error) {
      console.error('Error saving draft:', error)
      alert('Taslak kaydedilirken beklenmedik bir hata oluştu!')
    }
  }

  const publishNews = async () => {
    if (!formData.title || !formData.content || !formData.category) {
      alert('Lütfen zorunlu alanları doldurun!')
      return
    }

    try {
      const publishedData = {
        ...formData,
        image_url: formData.imageUrl,
        is_published: formData.isPublished,
        is_draft: formData.isDraft
      }
      const success = await addNews(publishedData)

      if (success) {
        localStorage.removeItem('newsDraft') // Yayınlandı, localStorage'ı temizle
        alert('Haber başarıyla yayınlandı!')
        // Formu sıfırla
        setFormData({
          title: '',
          excerpt: '',
          content: '',
          category: '',
          author: '',
          featured: false,
          imageUrl: '',
          images: [],
          videoUrl: '',
          isPublished: false,
          isDraft: true,
        })
      } else {
        alert('Haber yayınlanırken hata oluştu!')
      }
    } catch (error) {
      console.error('Error publishing news:', error)
      alert('Haber yayınlanırken beklenmedik bir hata oluştu!')
    }
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <Link href="/admin" className="text-blue-400 hover:underline mb-4 inline-block">
            ← Admin Paneline Dön
          </Link>
          <h1 className="text-3xl font-bold">Yeni Haber Oluştur</h1>
          <p className="text-gray-400 mt-2">Detaylı bir haber oluşturmak için formu doldurun</p>
        </div>

        {/* Form */}
        <form className="bg-gray-800 rounded-lg p-8 space-y-6">
          {/* Başlık */}
          <div>
            <label className="block text-sm font-semibold mb-2">Başlık *</label>
            <input
              type="text"
              name="title"
              value={formData.title}
              onChange={handleInputChange}
              placeholder="Haber başlığını yazın..."
              className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
              required
            />
          </div>

          {/* Özet */}
          <div>
            <label className="block text-sm font-semibold mb-2">Özet *</label>
            <textarea
              name="excerpt"
              value={formData.excerpt}
              onChange={handleInputChange}
              placeholder="Haber özetini yazın (maksimum 150 karakter)..."
              rows={2}
              className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
              required
            />
          </div>

          {/* İçerik */}
          <div>
            <label className="block text-sm font-semibold mb-2">İçerik *</label>
            <textarea
              name="content"
              value={formData.content}
              onChange={handleInputChange}
              placeholder="Haber içeriğini yazın..."
              rows={8}
              className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
              required
            />
          </div>

          {/* Kategori ve Yazar */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-semibold mb-2">Kategori *</label>
              <select
                name="category"
                value={formData.category}
                onChange={handleInputChange}
                className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
                required
              >
                <option value="">Kategori Seçin</option>
                {categories.map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-semibold mb-2">Yazar *</label>
              <input
                type="text"
                name="author"
                value={formData.author}
                onChange={handleInputChange}
                placeholder="Yazar adı..."
                className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
                required
              />
            </div>
          </div>

          {/* Öne Çıkan */}
          <div className="flex items-center">
            <input
              type="checkbox"
              name="featured"
              checked={formData.featured}
              onChange={handleInputChange}
              className="w-4 h-4"
            />
            <label className="ml-2 text-sm">Bu haberi öne çıkart</label>
          </div>
          {/* Resim URL - Eski sistem için fallback */}
          <div>
            <label className="block text-sm font-semibold mb-2">Ana Resim URL (Alternatif)</label>
            <input
              type="url"
              name="imageUrl"
              value={formData.imageUrl}
              onChange={handleInputChange}
              placeholder="https://example.com/image.jpg"
              className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
            />
            {formData.imageUrl && (
              <div className="mt-2">
                <img
                  src={formData.imageUrl}
                  alt="Ana görsel"
                  className="w-32 h-24 object-cover rounded-lg"
                />
              </div>
            )}
          </div>

          {/* Video URL */}
          <div>
            <label className="block text-sm font-semibold mb-2">Video URL (İsteğe bağlı)</label>
            <input
              type="url"
              name="videoUrl"
              value={formData.videoUrl || ''}
              onChange={handleInputChange}
              placeholder="YouTube, Vimeo veya başka bir video URL'si..."
              className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-2 focus:border-blue-500 focus:outline-none"
            />
            {formData.videoUrl && (
              <div className="mt-2 text-sm text-gray-400">
                Video URL eklendi: {formData.videoUrl.length > 50 ? formData.videoUrl.substring(0, 50) + '...' : formData.videoUrl}
              </div>
            )}
          </div>
          <div>
            <label className="block text-sm font-semibold mb-2">Resimler (Modern Yükleme Sistemi)</label>
            <ImageUpload
              onImageSelect={handleImageSelect}
              currentImages={formData.images}
              onRemoveImage={handleRemoveImage}
              maxImages={10}
            />
          </div>
          {/* Auto-save durumu */}
          <div className="flex items-center justify-between bg-gray-700 p-4 rounded-lg">
            <div className="flex items-center gap-4">
              <div className="flex items-center">
                <input
                  type="checkbox"
                  checked={autoSaveEnabled}
                  onChange={(e) => setAutoSaveEnabled(e.target.checked)}
                  className="w-4 h-4 mr-2"
                />
                <label className="text-sm">Otomatik kaydetmeyi etkinleştir</label>
              </div>
              {lastSaved && (
                <span className="text-sm text-green-400">Son kaydedilme: {lastSaved}</span>
              )}
            </div>
          </div>

          {/* Butonlar */}
          <div className="flex gap-4 pt-4">
            <button
              type="button"
              onClick={publishNews}
              className="bg-blue-600 hover:bg-blue-700 px-8 py-3 rounded-lg font-semibold transition"
            >
              📤 Haber Yayınla
            </button>
            <button
              type="button"
              onClick={saveAsDraft}
              className="bg-gray-700 hover:bg-gray-600 px-8 py-3 rounded-lg font-semibold transition"
            >
              💾 Taslak Olarak Kaydet
            </button>
            <Link href="/admin" className="bg-gray-600 hover:bg-gray-700 px-8 py-3 rounded-lg font-semibold transition text-center">
              ❌ İptal
            </Link>
          </div>
        </form>
      </div>
    </div>
  )
}